begin;
-- Refuse recovery after business activity; never erase history.
do $$ begin
 if (select md5(coalesce(string_agg((to_jsonb(t)-array['public_details'])::text,'' order by (to_jsonb(t)-array['public_details'])::text),'')) from public.companies t)<>'7aae40d6724690c55601d0c7a4761d35' then raise exception 'RECOVERY_BLOCKED_companies_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t))::text,'' order by (to_jsonb(t))::text),'')) from public.company_assets t)<>'8c85ac2d56b3018cee080a3d3229ac6b' then raise exception 'RECOVERY_BLOCKED_company_assets_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t)-array['description','conditions'])::text,'' order by (to_jsonb(t)-array['description','conditions'])::text),'')) from public.company_benefit_profiles t)<>'d41d8cd98f00b204e9800998ecf8427e' then raise exception 'RECOVERY_BLOCKED_company_benefit_profiles_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t))::text,'' order by (to_jsonb(t))::text),'')) from public.company_benefits t)<>'d41d8cd98f00b204e9800998ecf8427e' then raise exception 'RECOVERY_BLOCKED_company_benefits_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t))::text,'' order by (to_jsonb(t))::text),'')) from public.company_audience_rules t)<>'d41d8cd98f00b204e9800998ecf8427e' then raise exception 'RECOVERY_BLOCKED_company_audience_rules_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t)-array['public_details','cover_asset_id'])::text,'' order by (to_jsonb(t)-array['public_details','cover_asset_id'])::text),'')) from public.educational_resources t)<>'39a743d415962aef48721caa9b70a2ca' then raise exception 'RECOVERY_BLOCKED_educational_resources_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t))::text,'' order by (to_jsonb(t))::text),'')) from public.marketplace_products t)<>'d41d8cd98f00b204e9800998ecf8427e' then raise exception 'RECOVERY_BLOCKED_marketplace_products_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t))::text,'' order by (to_jsonb(t))::text),'')) from public.marketplace_promotions t)<>'d41d8cd98f00b204e9800998ecf8427e' then raise exception 'RECOVERY_BLOCKED_marketplace_promotions_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t)-array['payment_reference','payment_amount','accredited_by','accredited_at'])::text,'' order by (to_jsonb(t)-array['payment_reference','payment_amount','accredited_by','accredited_at'])::text),'')) from public.company_portal_subscriptions t)<>'d41d8cd98f00b204e9800998ecf8427e' then raise exception 'RECOVERY_BLOCKED_company_portal_subscriptions_CHANGED';end if;
 if (select md5(coalesce(string_agg((to_jsonb(t))::text,'' order by (to_jsonb(t))::text),'')) from public.marketplace_company_memberships t)<>'d41d8cd98f00b204e9800998ecf8427e' then raise exception 'RECOVERY_BLOCKED_marketplace_company_memberships_CHANGED';end if;
 if exists(select 1 from public.companies where public_details<>'{}') or exists(select 1 from public.educational_resources where public_details<>'{}' or cover_asset_id is not null) or exists(select 1 from public.company_benefit_profiles where description<>'' or conditions<>'') or exists(select 1 from public.educational_resource_favorites) or exists(select 1 from public.company_portal_plans where id::text like 'cc000000%' and updated_at<>created_at) then raise exception 'RECOVERY_BLOCKED_NEW_HISTORY';end if;
end $$;
drop policy education_favorite_self on public.educational_resource_favorites;
drop policy company_ficha_image_upload on storage.objects;
drop policy company_portal_plans_read on public.company_portal_plans;
drop policy agreement_product_insert on public.marketplace_products;
drop policy agreement_product_update on public.marketplace_products;
drop policy agreement_product_delete on public.marketplace_products;
drop policy agreement_product_read on public.marketplace_products;
drop policy agreement_product_asset_write on public.marketplace_product_assets;
create policy company_portal_plans_read on public.company_portal_plans for select to authenticated using((has_admin_permission('company_portal.read'::text) OR (EXISTS ( SELECT 1
   FROM company_portal_subscriptions s
  WHERE ((s.plan_id = s.id) AND is_marketplace_company_member(s.company_id))))));
drop trigger companies_section_action_guard on public.companies;
CREATE TRIGGER companies_section_action_guard BEFORE INSERT OR DELETE OR UPDATE ON public.companies FOR EACH ROW EXECUTE FUNCTION enforce_section_row_action('companies', 'companies.write', 'enabled', 'sort_order', 'logo_asset_id', 'record_origin', 'ADMIN_H009');
