drop trigger marketplace_products_section_action_guard on public.marketplace_products;
CREATE TRIGGER marketplace_products_section_action_guard BEFORE INSERT OR DELETE OR UPDATE ON public.marketplace_products FOR EACH ROW EXECUTE FUNCTION enforce_section_row_action('marketplace', 'marketplace.write', 'enabled', 'sort_order', '', 'record_origin', 'ADMIN_PHASE3');
drop trigger marketplace_product_assets_section_action_guard on public.marketplace_product_assets;
CREATE TRIGGER marketplace_product_assets_section_action_guard BEFORE INSERT OR DELETE OR UPDATE ON public.marketplace_product_assets FOR EACH ROW EXECUTE FUNCTION enforce_section_row_action('marketplace', 'marketplace.write', '', 'sort_order', 'asset_id', 'record_origin', 'ADMIN_PHASE3');
drop trigger educational_resources_section_action_guard on public.educational_resources;
CREATE TRIGGER educational_resources_section_action_guard BEFORE INSERT OR DELETE OR UPDATE ON public.educational_resources FOR EACH ROW EXECUTE FUNCTION enforce_section_row_action('education', 'content.write', 'published', 'sort_order', 'image_asset_id,document_asset_id', 'provenance', 'ADMIN_PHASE2');
