delete from public.company_portal_plans where id in ('cc000000-0000-4000-8000-000000000001','cc000000-0000-4000-8000-000000000002','cc000000-0000-4000-8000-000000000003');
alter table public.companies drop column public_details;
alter table public.educational_resources drop column public_details;
alter table public.educational_resources drop column cover_asset_id;
